"""Render the Russian summary from matched-query measurements."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
def read(name):return json.loads((ROOT/name).read_bytes())
def num(x,digits=2):return f'{x:.{digits}f}'.replace('.',',')
def contrast(x):
    v=x['differences']['full_support']
    return f"{num(100*v['estimate'])} п.п. [{num(100*v['cluster_ci95'][0])}; {num(100*v['cluster_ci95'][1])}]"
def main():
    a=read('results.json'); support=read('common-support.json')
    ec,ph=read('encoding-cost.json'),read('physical-cost.json')
    section=['# Как извлечь свидетельства из памяти, которая уже отбросила часть траектории',
    '',
    'На официальных запросах ISETrace пишущая модель и несколько читателей получают разные части информации. Во время записи доступен завершённый аргумент или результат действия, будущий вопрос скрыт. Логистическая модель full оценивает роль, тип инструмента, длину и положение блока, а также признаки его текста. Эвристика output_head предпочитает начало результатов инструментов. FIFO сохраняет последние блоки. После поступления вопроса читатель видит только оставшуюся память. Блоки около 64 токенов, максимальное хранение 8 192 WordPiece, выдача 2 048. Вычисления сделаны по полным test (2 000 вопросов, 1 207 траекторий) и dev (580 вопросов, 352 траектории). [Постановка](PROTOCOL_RU.md) · [Пишущая модель](../write_learned/REPORT_RU.md)',
    '']
    for st in ['test','dev']:
        m=a[st]['metrics'];p=a[st]['contrasts']['full/dense-output_head/dense']
        section+=[f"## {st}",
         '',
         f"При фиксированном Dense-FT обученная запись дала **{m['full/dense']['hits']}/{a[st]['n']}** полностью подтверждённых ответных контекстов, output_head — **{m['output_head/dense']['hits']}/{a[st]['n']}**. Парная разница **{contrast(p)}**, {p['fs_wins']} выигрышей, {p['fs_losses']} потерь и {p['fs_ties']} совпадений. 95% ДИ получен бутстрепом 10 000 раз по траекториям, разница посчитана по запросам. Это метрика наличия всех gold-символов в выдаче. Ответ LLM на этих запросах в данном сравнении не измерялся.",
        '',
        '| Запись | Чтение | Полный комплект в памяти, % | Полный комплект в выдаче, случаи | FS, % | Coverage, % | Density, % | F1, % | Токены чтения |',
        '|---|---|---:|---:|---:|---:|---:|---:|---:|']
        for w in ('full','output_head','fifo'):
            for r in ('bm25','dense','rrf60'):
                s=m[w+'/'+r];vals=[num(100*s[k]) for k in ('full_support','coverage','density','f1')]
                section.append('| '+' | '.join([w,r,num(100*s['write_fs']),str(s['hits']),*vals,num(s['tokens'],1)])+' |')
        section+=['',f"У full смена BM25 на Dense-FT даёт {contrast(a[st]['contrasts']['full/dense-full/bm25'])}; фиксированная комбинация BM25 и Dense-FT (взаимный ранг, k=60) относительно BM25 — {contrast(a[st]['contrasts']['full/rrf60-full/bm25'])}. Эти вторичные интервалы рассчитаны отдельно, без коррекции множественных сравнений. [Исходы всех запросов](outcomes.json.gz) · [Все контрасты](results.json)",'']
    s=support['test']['dense']['cells']
    section+=['## За счёт чего меняется результат', '',
        'Координаты gold после прогнозирования позволяют определить, сможет ли идеальный читатель восстановить весь комплект свидетельств. Ниже учтены все четыре сочетания. Это разложение наблюдаемой разницы по исходам записи.',
        '', '| Что осталось после записи | Запросов | Полная выдача у full | Полная выдача у output_head | Разность, случаев |','|---|---:|---:|---:|---:|']
    for k,n in [('11','В обеих памятях'),('10','Только у full'),('01','Только у output_head'),('00','У обоих неполный комплект')]:
        v=s[k];section.append(f"| {n} | {v['n']} | {v['full_reader_hits']} | {v['output_head_reader_hits']} | {v['full_reader_hits']-v['output_head_reader_hits']:+} |")
    c=s['11']; extra=s['10']['full_reader_hits']-s['01']['output_head_reader_hits']; both=c['full_reader_hits']-c['output_head_reader_hits']
    section+=['',f"На test сохранение полного комплекта только одним писателем объясняет {extra:+} извлечённых комплектов в пользу full. В {c['n']} запросах, где оба писателя сохранили всё, разность составляет {both:+} случаев. В сумме {extra+both:+}. Результат совместим с увеличением доступности свидетельств при ограничении записи. Состав постфактум выделенных групп зависит от обеих политик.",'','Исходные 500 из 580 dev-вопросов участвовали в выборе эпохи Dense-FT. Остальные 80 могут разделять траектории с этими 500. На этой дополнительной части dev Dense-FT извлёк все свидетельства у full в '+str(support['dev80']['dense']['full_hits'])+' и у output_head в '+str(support['dev80']['dense']['head_hits'])+' случаях. Структура хранения и прежние результаты BM25 были известны до этого опыта. [Разложение для всех читателей](common-support.json) · [Дополнительный протокол](COMMON_SUPPORT_RU.md)',
        '','## Цена хранения и чтения', '',
        '| Запись | Токены в памяти на test-траекторию | Блоки | Текст UTF-8, КиБ | Текст с координатами и записями событий, КиБ | Доп. векторы FP32, КиБ |',
        '|---|---:|---:|---:|---:|---:|']
    for w,v in a['test']['storage'].items():
        section.append('| '+' | '.join([w,num(v['stored_tokens'],1),num(v['count'],1),num(v['utf8_bytes']/1024,1),num(v['text_wire_bytes']/1024,1),num(v['fp32_vector_bytes']/1024,1)])+' |')
    section+=['',f"Общий обученный E5 содержит 109,5 млн параметров. Его каталог вместе с токенизатором занимает {ph['full_checkpoint_bytes']:,} байт. Компактные параметры full занимают ещё 3 911 байт. На RTX 3090 за {num(ec['seconds'],1)} с закодированы {ec['unique']:,} уникальных точных строк и вопросов из обеих выборок. Вход составил {ec['exact_unpadded_model_tokens']:,} токенов E5 без паддинга, пик выделения PyTorch — {num(ec['peak_torch_gib'])} ГиБ. Плоские FP32-векторы по 3 072 байта требуют {ph['vector_payload_bytes']:,} байт. Экспериментальная SQLite с текстом, ключами и векторами занимает {ph['combined_sqlite_bytes']:,} байт. Эта база обслуживает все траектории и три политики с дедупликацией. Для реализации отдельного агента плоский индекс оплачивается отдельно от текстового лимита; повторное кодирование при чтении заменило бы этот расход вычислениями. [Физический учёт](physical-cost.json) · [Журнал кодирования](encoding-cost.json)",
        '', 'Срезы и их SHA сверены с источниками для всех 376 886 вхождений блоков в объединении трёх памятей. Стоимость повторно определена авторским токенизатором; после среза встречается до 66 токенов. Модель получила точную строку каждого сохранившегося фрагмента. Предшествующий encoder обучен на полном train, одна и та же эпоха использована во всех девяти условиях. Выходы BM25 сверены индивидуально с предшествующей серией. [Проверка источников](source-verification.json) · [Обучение Dense-FT](../trained_rank/REPORT_RU.md) · [Фиксация прогнозов](forecast-seal.json)',
        '', 'Сопоставление с опубликованными Dense-FT и R-GCN из Table 1 требует учитывать, что там доступна полная история и единицы другого размера. Настоящий результат оценивает политику записи при явном необратимом ограничении памяти. Один seed и один benchmark ограничивают переносимость. [Опубликованная таблица ISETrace](https://arxiv.org/html/2609.25913v3#S6.T1) · [Воспроизведение](REPRODUCE_RU.md)']
    (ROOT/'REPORT_RU.md').write_text('\n'.join(section)+'\n',encoding='utf8')
if __name__=='__main__':main()

